-- 466 — Reimbursement Approvals.
--
--  • A Trip Summary / Combined Trip Summary generated by a driver or
--    salesperson (not an admin's look) becomes a claim the first time it is
--    generated. Generating it again only counts it ("generated 3×").
--  • Claim lines are per trip, so a later summary that covers trips already
--    paid shows "partly / fully paid" and leaves them out of the amount.
--  • Approvers (Admin Settings → org.reimb_approvers; nobody picked = admins)
--    approve or reject. Accounts mark paid (org.reimb_payers when
--    org.reimb_payers_only is on; otherwise anyone who can open the screen).
--  • Notifications: events reimb_submitted / reimb_approved / reimb_rejected /
--    reimb_paid — recipients set in Admin Settings → Notifications.
--  • Recording is switched on by Admin Settings → org.reimb_approvals.
--    Rate per km: org.reimb_rate_km (0 / empty = amount typed when paying).
-- Safe to run again.

create table if not exists public.reimb_claims (
  id                 text primary key default ('rmb_' || replace(gen_random_uuid()::text, '-', '')),
  org_id             text not null,
  claimant_id        text not null,
  claimant_name      text,
  doc_type           text not null,            -- trip_summary | combined_summary
  doc_key            text not null,
  date_from          date,
  date_to            date,
  km                 numeric not null default 0,
  trips              int not null default 0,
  status             text not null default 'pending', -- pending | approved | paid | rejected
  generated_count    int not null default 1,
  first_generated_at timestamptz not null default now(),
  last_generated_at  timestamptz not null default now(),
  generated_by_name  text,
  rate               numeric,
  unpaid_km          numeric,
  amount             numeric,
  decided_by_name    text,
  decided_at         timestamptz,
  reject_reason      text,
  paid_amount        numeric,
  paid_on            date,
  paid_method        text,
  paid_ref           text,
  paid_by_name       text,
  paid_at            timestamptz,
  created_at         timestamptz not null default now(),
  unique (org_id, doc_type, doc_key)
);
create index if not exists reimb_claims_org on public.reimb_claims (org_id, status);

create table if not exists public.reimb_lines (
  claim_id  text not null,
  org_id    text not null,
  trip_id   text not null,
  day       date not null,
  km        numeric not null default 0,
  primary key (claim_id, trip_id)
);
create index if not exists reimb_lines_trip on public.reimb_lines (org_id, trip_id);

create table if not exists public.reimb_trip_paid (
  org_id   text not null,
  trip_id  text not null,
  claim_id text not null,
  paid_on  date,
  primary key (org_id, trip_id)
);

do $$
declare t text;
begin
  foreach t in array array['reimb_claims','reimb_lines','reimb_trip_paid'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format('create policy %I on public.%I for select using (public._is_org_member(org_id) or public._is_super_admin())', t || '_read', t);
    execute format('revoke insert, update, delete on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- Is the acting user in a comma-separated user list in app_config?
create or replace function public._reimb_in_list(p_org text, p_key text)
returns boolean language plpgsql stable security definer set search_path to 'public' as $$
declare v_me text; v_list text[];
begin
  select a.id into v_me from public._acting_user(p_org) a;
  if v_me is null then return false; end if;
  select string_to_array(replace(coalesce(value, ''), ' ', ''), ',') into v_list
    from app_config where org_id = p_org and key = p_key and branch_id is null limit 1;
  return v_me = any (coalesce(v_list, '{}'));
end $$;

create or replace function public._reimb_list_empty(p_org text, p_key text)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select coalesce((select btrim(value) from app_config where org_id = p_org and key = p_key and branch_id is null limit 1), '') = ''
$$;

create or replace function public.reimb_can_approve(p_org text)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select public._is_super_admin()
      or (public._is_org_member(p_org) and (
            public._reimb_in_list(p_org, 'org.reimb_approvers')
         or (public._reimb_list_empty(p_org, 'org.reimb_approvers') and exists (
               select 1 from public._acting_user(p_org) a join users u on u.id = a.id
                where u.org_id = p_org and u.role in ('admin', 'masterAdmin', 'superAdmin')))))
$$;
grant execute on function public.reimb_can_approve(text) to authenticated;

create or replace function public.reimb_can_pay(p_org text)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select public._is_super_admin()
      or (public._is_org_member(p_org) and (
            not public._cfg_true(p_org, 'org.reimb_payers_only')
         or public._reimb_in_list(p_org, 'org.reimb_payers')))
$$;
grant execute on function public.reimb_can_pay(text) to authenticated;

create or replace function public._reimb_rate(p_org text)
returns numeric language sql stable security definer set search_path to 'public' as $$
  select case when v ~ '^[0-9]+(\.[0-9]+)?$' and v::numeric > 0 then v::numeric end
    from (select btrim(coalesce((select value from app_config where org_id = p_org and key = 'org.reimb_rate_km'
                                   and branch_id is null limit 1), '')) as v) x
$$;

-- Called by the web and the app every time a trip summary is generated.
-- p_lines: [{trip, day: 'YYYY-MM-DD', km}]. p_record = a real issue by the
-- driver / salesperson (admins only look). Returns the rate and which of
-- these trips were already paid, for the PDF stamp.
create or replace function public.reimb_submit(p_org text, p_type text, p_key text, p_claimant text,
                                               p_lines jsonb, p_record boolean default true)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_lines jsonb := coalesce(p_lines, '[]'::jsonb);
  v_id text; v_new boolean := false; v_from date; v_to date; v_km numeric; v_n int;
  v_rate numeric; v_paid jsonb; v_name text; v_by text; v_status text; c reimb_claims%rowtype;
begin
  if not (public._is_org_member(p_org) or public._is_super_admin()) then return null; end if;
  v_rate := public._reimb_rate(p_org);

  if p_record and p_claimant is not null and public._cfg_true(p_org, 'org.reimb_approvals')
     and jsonb_typeof(v_lines) = 'array' and jsonb_array_length(v_lines) > 0 then
    select min((l->>'day')::date), max((l->>'day')::date), round(sum(coalesce((l->>'km')::numeric, 0)), 2), count(*)
      into v_from, v_to, v_km, v_n
      from jsonb_array_elements(v_lines) l;
    select name into v_name from users where id = p_claimant;
    select a.name into v_by from public._acting_user(p_org) a;

    insert into reimb_claims (org_id, claimant_id, claimant_name, doc_type, doc_key, date_from, date_to, km, trips, generated_by_name)
    values (p_org, p_claimant, v_name, p_type, p_key, v_from, v_to, v_km, v_n, coalesce(v_by, v_name))
    on conflict (org_id, doc_type, doc_key) do update
       set generated_count = reimb_claims.generated_count + 1, last_generated_at = now()
    returning id, (xmax = 0) into v_id, v_new;

    if v_new then
      insert into reimb_lines (claim_id, org_id, trip_id, day, km)
      select v_id, p_org, l->>'trip', (l->>'day')::date, round(coalesce((l->>'km')::numeric, 0), 2)
        from jsonb_array_elements(v_lines) l
       where coalesce(l->>'trip', '') <> ''
      on conflict do nothing;
      begin
        perform public.notify_event(p_org, 'reimb_submitted', null, p_claimant,
          'Trip summary to approve — ' || coalesce(v_name, ''),
          case when v_from = v_to then to_char(v_from, 'DD Mon') else to_char(v_from, 'DD Mon') || ' – ' || to_char(v_to, 'DD Mon') end
            || ' · ' || v_km || ' km' || coalesce(' · Rs ' || to_char(round(v_km * v_rate), 'FM999,999,999'), ''),
          '/reimbursements?c=' || v_id);
      exception when others then null;
      end;
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('trip', l.trip, 'day', l.day, 'paid_on', p.paid_on,
                                               'ref', c2.paid_ref, 'claim', p.claim_id) order by l.day), '[]'::jsonb)
    into v_paid
    from (select distinct l->>'trip' as trip, (l->>'day')::date as day from jsonb_array_elements(v_lines) l) l
    join reimb_trip_paid p on p.org_id = p_org and p.trip_id = l.trip
    left join reimb_claims c2 on c2.id = p.claim_id;

  if v_id is null then
    select * into c from reimb_claims where org_id = p_org and doc_type = p_type and doc_key = p_key;
  else
    select * into c from reimb_claims where id = v_id;
  end if;

  return jsonb_build_object('rate', v_rate, 'paid', v_paid, 'claim', c.id, 'status', c.status,
                            'paid_amount', c.paid_amount, 'paid_on', c.paid_on, 'paid_ref', c.paid_ref,
                            'paid_method', c.paid_method, 'approved_by', c.decided_by_name);
end $$;
grant execute on function public.reimb_submit(text, text, text, text, jsonb, boolean) to authenticated;

-- Km of a claim not already paid by another claim.
create or replace function public._reimb_unpaid_km(p_claim text)
returns numeric language sql stable security definer set search_path to 'public' as $$
  select coalesce(sum(l.km), 0) from reimb_lines l
   where l.claim_id = p_claim
     and not exists (select 1 from reimb_trip_paid p where p.org_id = l.org_id and p.trip_id = l.trip_id and p.claim_id <> p_claim)
$$;

create or replace function public.reimb_decide(p_claim text, p_approve boolean, p_reason text default null)
returns void language plpgsql security definer set search_path to 'public' as $$
declare c reimb_claims%rowtype; v_by text; v_unpaid numeric; v_rate numeric;
begin
  select * into c from reimb_claims where id = p_claim;
  if c.id is null then raise exception 'Claim not found.'; end if;
  if not public.reimb_can_approve(c.org_id) then raise exception 'You are not an approver for reimbursements.'; end if;
  if c.status not in ('pending', 'rejected') and p_approve then raise exception 'This claim is already %.', c.status; end if;
  if c.status <> 'pending' and not p_approve then raise exception 'Only a pending claim can be rejected.'; end if;
  if not p_approve and nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'Enter the reason.'; end if;
  select a.name into v_by from public._acting_user(c.org_id) a;
  v_unpaid := public._reimb_unpaid_km(c.id);
  v_rate := public._reimb_rate(c.org_id);
  update reimb_claims
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by_name = v_by, decided_at = now(),
         reject_reason = case when p_approve then null else btrim(p_reason) end,
         rate = v_rate, unpaid_km = v_unpaid,
         amount = case when v_rate is not null then round(v_unpaid * v_rate) end
   where id = c.id;
  begin
    if p_approve then
      perform public.notify_event(c.org_id, 'reimb_approved', null, c.claimant_id,
        'Reimbursement approved — ' || coalesce(c.claimant_name, ''),
        v_unpaid || ' km' || coalesce(' · Rs ' || to_char(round(v_unpaid * v_rate), 'FM999,999,999'), '') || ' · approved by ' || coalesce(v_by, ''),
        '/reimbursements?c=' || c.id);
    else
      perform public.notify_event(c.org_id, 'reimb_rejected', null, c.claimant_id,
        'Reimbursement rejected — ' || coalesce(c.claimant_name, ''),
        btrim(p_reason) || ' (' || coalesce(v_by, '') || ')', '/reimbursements?c=' || c.id);
    end if;
  exception when others then null;
  end;
end $$;
grant execute on function public.reimb_decide(text, boolean, text) to authenticated;

create or replace function public.reimb_mark_paid(p_claim text, p_amount numeric, p_paid_on date,
                                                  p_method text default null, p_ref text default null)
returns void language plpgsql security definer set search_path to 'public' as $$
declare c reimb_claims%rowtype; v_by text;
begin
  select * into c from reimb_claims where id = p_claim;
  if c.id is null then raise exception 'Claim not found.'; end if;
  if not public.reimb_can_pay(c.org_id) then raise exception 'You cannot mark reimbursements paid.'; end if;
  if c.status <> 'approved' then raise exception 'Only an approved claim can be marked paid.'; end if;
  if p_amount is null or p_amount < 0 then raise exception 'Enter the amount paid.'; end if;
  select a.name into v_by from public._acting_user(c.org_id) a;
  update reimb_claims
     set status = 'paid', paid_amount = p_amount, paid_on = coalesce(p_paid_on, (now() at time zone 'Asia/Karachi')::date),
         paid_method = nullif(btrim(coalesce(p_method, '')), ''), paid_ref = nullif(btrim(coalesce(p_ref, '')), ''),
         paid_by_name = v_by, paid_at = now()
   where id = c.id;
  insert into reimb_trip_paid (org_id, trip_id, claim_id, paid_on)
  select c.org_id, l.trip_id, c.id, coalesce(p_paid_on, (now() at time zone 'Asia/Karachi')::date)
    from reimb_lines l where l.claim_id = c.id
  on conflict (org_id, trip_id) do nothing;
  begin
    perform public.notify_event(c.org_id, 'reimb_paid', null, c.claimant_id,
      'Reimbursement paid — ' || coalesce(c.claimant_name, ''),
      'Rs ' || to_char(p_amount, 'FM999,999,999') || coalesce(' · ' || nullif(btrim(coalesce(p_method, '')), ''), '')
        || coalesce(' · ref ' || nullif(btrim(coalesce(p_ref, '')), ''), ''),
      '/reimbursements?c=' || c.id);
  exception when others then null;
  end;
end $$;
grant execute on function public.reimb_mark_paid(text, numeric, date, text, text) to authenticated;

-- Menu counter: pending (for approvers) + approved (for payers).
create or replace function public.reimb_todo_count(p_org text)
returns int language plpgsql stable security definer set search_path to 'public' as $$
declare n int := 0;
begin
  if not (public._is_org_member(p_org) or public._is_super_admin()) then return 0; end if;
  if public.reimb_can_approve(p_org) then
    n := n + (select count(*) from reimb_claims where org_id = p_org and status = 'pending');
  end if;
  if public.reimb_can_pay(p_org) then
    n := n + (select count(*) from reimb_claims where org_id = p_org and status = 'approved');
  end if;
  return n;
end $$;
grant execute on function public.reimb_todo_count(text) to authenticated;
